alert:
import { Alert, AlertDescription, AlertTitle, type AlertProps } from 'splatoon-ui/alert'

type AlertExampleProps = {
  variant: AlertProps['variant']
}

export function AlertExample({ variant }: AlertExampleProps) {
  return (
    <Alert className="max-w-md" variant={variant}>
      <AlertTitle>Fresh update</AlertTitle>
      <AlertDescription>Use alerts for compact status updates.</AlertDescription>
    </Alert>
  )
}

badge:
import { Badge, type BadgeProps } from 'splatoon-ui/badge'

type BadgeExampleProps = {
  color: BadgeProps['color']
  label: string
}

export function BadgeExample({ color, label }: BadgeExampleProps) {
  return <Badge color={color}>{label}</Badge>
}

button:
import { Button, type ButtonProps } from 'splatoon-ui/button'

type ButtonExampleProps = {
  variant: ButtonProps['variant']
  size: ButtonProps['size']
  label: string
  hasChevron: boolean
}

export function ButtonExample({ variant, size, label, hasChevron }: ButtonExampleProps) {
  return (
    <Button variant={variant} size={size} hasChevron={hasChevron}>
      {label}
    </Button>
  )
}

checkbox:
import { Checkbox } from 'splatoon-ui/checkbox'

type CheckboxExampleProps = {
  checked: boolean
}

export function CheckboxExample({ checked }: CheckboxExampleProps) {
  return (
    <label className="flex items-center gap-3 font-bold">
      <Checkbox checked={checked} readOnly />
      Ready for ranked
    </label>
  )
}

dialog:
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
  DialogTriggerButton,
} from 'splatoon-ui/dialog'

type DialogExampleProps = {
  title: string
}

export function DialogExample({ title }: DialogExampleProps) {
  return (
    <Dialog>
      <DialogTriggerButton>{title}</DialogTriggerButton>
      <DialogContent>
        <DialogHeader>
          <DialogTitle>{title}</DialogTitle>
          <DialogDescription>Use dialogs for focused decisions.</DialogDescription>
        </DialogHeader>
      </DialogContent>
    </Dialog>
  )
}

input:
import { Input } from 'splatoon-ui/input'

type InputExampleProps = {
  value: string
}

export function InputExample({ value }: InputExampleProps) {
  return (
    <div className="grid w-full max-w-sm gap-2">
      <label className="text-sm font-black tracking-wider" htmlFor="docs-input-example">
        Player name
      </label>
      <Input id="docs-input-example" value={value} readOnly />
    </div>
  )
}

progress:
import { Progress, type ProgressProps } from 'splatoon-ui/progress'

type ProgressExampleProps = {
  value: number
  variant: ProgressProps['variant']
}

export function ProgressExample({ value, variant }: ProgressExampleProps) {
  return (
    <div className="w-full max-w-md">
      <Progress value={value} variant={variant} />
    </div>
  )
}

switch:
import { Switch, type SwitchProps } from 'splatoon-ui/switch'

type SwitchExampleProps = {
  color: SwitchProps['color']
  checked: boolean
}

export function SwitchExample({ color, checked }: SwitchExampleProps) {
  return <Switch checked={checked} color={color} aria-label="Enable turf mode" />
}

tabs:
import {
  Tabs,
  TabsContent,
  TabsList,
  TabsPanels,
  TabsTrigger,
  type TabsListProps,
} from 'splatoon-ui/tabs'

type TabsExampleProps = {
  variant: TabsListProps['variant']
}

export function TabsExample({ variant }: TabsExampleProps) {
  return (
    <Tabs defaultValue="weapons" className="w-full max-w-md">
      <TabsList variant={variant}>
        <TabsTrigger value="weapons">Weapons</TabsTrigger>
        <TabsTrigger value="maps">Maps</TabsTrigger>
      </TabsList>
      <TabsPanels className="mt-4">
        <TabsContent value="weapons">Blasters, rollers, and chargers.</TabsContent>
        <TabsContent value="maps">Compact map rotation details.</TabsContent>
      </TabsPanels>
    </Tabs>
  )
}
